const titles={th:'Web App & AI สำหรับงานก่อสร้าง',en:'siamkosi | Construction Web Apps & AI Automation'};
function setLanguage(lang){document.documentElement.lang=lang;document.title=titles[lang];document.querySelectorAll('[data-th]').forEach(el=>el.innerHTML=el.dataset[lang]);document.querySelectorAll('[data-alt-th]').forEach(el=>el.alt=el.dataset[lang==='th'?'altTh':'altEn']);document.querySelectorAll('[data-lang]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.lang===lang)));document.getElementById('close-viewer').setAttribute('aria-label',lang==='th'?'ปิดภาพ':'Close image');try{localStorage.setItem('siamkosi-language',lang)}catch{}}
let initial='th';try{initial=localStorage.getItem('siamkosi-language')==='en'?'en':'th'}catch{}setLanguage(initial);document.querySelectorAll('[data-lang]').forEach(b=>b.addEventListener('click',()=>setLanguage(b.dataset.lang)));
const viewer=document.getElementById('viewer');document.querySelectorAll('[data-image]').forEach(b=>b.addEventListener('click',()=>{const frame=viewer.querySelector('.viewer-frame');frame.className='viewer-frame'+(b.dataset.crop?' screen-crop':'');frame.style.cssText=b.dataset.crop?b.dataset.crop+'--viewer-ratio:'+b.dataset.ratio+';':'';viewer.querySelector('img').src=b.dataset.image;viewer.querySelector('img').alt=b.querySelector('img')?.alt||'LINE STORE';viewer.showModal()}));document.getElementById('close-viewer').addEventListener('click',()=>viewer.close());viewer.addEventListener('click',e=>{if(e.target===viewer)viewer.close()});
